-- =============================================================================
-- Demo catalogue, part 2: variants, stock, taxonomy links, relations.
--
-- Two deliberate omissions, both so the storefront exercises a real empty state rather
-- than a fake-looking one:
--
--  · **No product_images.** Placeholder paths would point at files that do not exist and
--    every `next/image` would 404. The UI renders a branded fallback tile instead, which is
--    a state docs/04 §9 requires anyway.
--  · **No reviews.** `reviews.user_id` needs real auth users, which come from
--    `scripts/seed-users.ts` (docs/11 §2, still outstanding). Ratings therefore stay at 0
--    and the "no reviews yet" path gets exercised. Inventing rating aggregates would also
--    desynchronise them from the trigger that owns them.
--
-- Stock fixtures required by docs/11 §7: the electrolyte tabs sit at 3 (low-stock queue)
-- and the 2.27 kg whey is at 0 (out-of-stock, visible but not addable per docs/07 §11).
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Variants. Prices are VAT-inclusive integer cents (CLAUDE.md §2).
-- -----------------------------------------------------------------------------
on conflict (id) do update set product_id = excluded.product_id, sku = excluded.sku, name = excluded.name,
  options = excluded.options, price_cents = excluded.price_cents,
  compare_at_price_cents = excluded.compare_at_price_cents, is_default = excluded.is_default,
  position = excluded.position;

-- -----------------------------------------------------------------------------
-- Opening stock.
--
-- `inventory_levels` and `stock_movements` are written together so the invariant in
-- docs/07 §11 (on_hand == sum of movements) holds from the first row — docs/13 §A7. The
-- `apply_stock_movement` RPC is not used here: it gates on `is_service_role()` or a staff
-- role, and a seed runs as the migration role, which is neither.
--
-- Movements are cleared and rewritten so re-running the seed cannot double them.
-- -----------------------------------------------------------------------------
delete from stock_movements where note = 'seed opening balance';

with levels(variant_id, on_hand) as (values
  ('c0000000-0000-4000-8000-000000000001'::uuid, 120), ('c0000000-0000-4000-8000-000000000002'::uuid, 64),
  ('c0000000-0000-4000-8000-000000000003'::uuid, 88),  ('c0000000-0000-4000-8000-000000000004'::uuid, 52),
  ('c0000000-0000-4000-8000-000000000005'::uuid, 75),  ('c0000000-0000-4000-8000-000000000006'::uuid, 40),
  ('c0000000-0000-4000-8000-000000000007'::uuid, 33),  ('c0000000-0000-4000-8000-000000000008'::uuid, 46),
  ('c0000000-0000-4000-8000-000000000009'::uuid, 29),
  -- docs/11 §7 — out-of-stock fixture: visible but not addable (docs/07 §11).
  ('c0000000-0000-4000-8000-00000000000a'::uuid, 0),
  ('c0000000-0000-4000-8000-00000000000b'::uuid, 61),  ('c0000000-0000-4000-8000-00000000000c'::uuid, 37),
  ('c0000000-0000-4000-8000-00000000000d'::uuid, 44),  ('c0000000-0000-4000-8000-00000000000e'::uuid, 21),
  ('c0000000-0000-4000-8000-00000000000f'::uuid, 58),  ('c0000000-0000-4000-8000-000000000010'::uuid, 96),
  ('c0000000-0000-4000-8000-000000000011'::uuid, 34),  ('c0000000-0000-4000-8000-000000000012'::uuid, 27),
  ('c0000000-0000-4000-8000-000000000013'::uuid, 42),  ('c0000000-0000-4000-8000-000000000014'::uuid, 55),
  ('c0000000-0000-4000-8000-000000000015'::uuid, 48),  ('c0000000-0000-4000-8000-000000000016'::uuid, 70),
  ('c0000000-0000-4000-8000-000000000017'::uuid, 39),  ('c0000000-0000-4000-8000-000000000018'::uuid, 45),
  ('c0000000-0000-4000-8000-000000000019'::uuid, 62),
  -- docs/11 §7 — low-stock fixture: feeds the dashboard queue via v_low_stock.
  ('c0000000-0000-4000-8000-00000000001a'::uuid, 3),
  ('c0000000-0000-4000-8000-00000000001b'::uuid, 51),  ('c0000000-0000-4000-8000-00000000001c'::uuid, 80),
  ('c0000000-0000-4000-8000-00000000001d'::uuid, 66),  ('c0000000-0000-4000-8000-00000000001e'::uuid, 25)
)
select l.variant_id, '11111111-0000-4000-8000-000000000001', l.on_hand, 5 from levels l
on conflict (variant_id, warehouse_id) do update set on_hand = excluded.on_hand;

select variant_id, warehouse_id, 'received', on_hand, 'seed opening balance'
  from inventory_levels where on_hand > 0;

-- -----------------------------------------------------------------------------
-- Categories (one primary each, per the `one_primary_category` index)
-- -----------------------------------------------------------------------------
on conflict (product_id, category_id) do update set is_primary = excluded.is_primary;

-- Sports products also sit under the parent category, so /shop/nutricion-sportiv is populated.
select product_id, '44444444-0000-4000-8000-000000000003', false
  from product_categories
 where category_id in ('44444444-0000-4000-8000-000000000004','44444444-0000-4000-8000-000000000005')
on conflict (product_id, category_id) do nothing;

-- -----------------------------------------------------------------------------
-- Health goals
-- -----------------------------------------------------------------------------
on conflict (product_id, goal_id) do nothing;

-- -----------------------------------------------------------------------------
-- Ingredient rows with amounts and %NRV where a reference value exists
-- -----------------------------------------------------------------------------
on conflict (product_id, ingredient_id) do update set amount = excluded.amount, unit = excluded.unit,
  nrv_pct = excluded.nrv_pct, position = excluded.position;

-- -----------------------------------------------------------------------------
-- Certifications on a handful of items (docs/11 §7)
-- -----------------------------------------------------------------------------
on conflict (product_id, certification_id) do nothing;

-- -----------------------------------------------------------------------------
-- Relations (docs/11 §7)
-- -----------------------------------------------------------------------------
on conflict (product_id, related_product_id, kind) do nothing;
